import {setFaultShutters} from './fault-shutters.js';
import {installFaultKeys,selectFaultLight,LIGHT_LEVELS} from './fault-lighting.js';
import {startFault,endFault} from './fault-experiment.js';import {faultMapSVG} from './fault-map.js';
export function installFaultControls({sim,$,setView,clearKeys,changed,viewMode=()=>'overview'}){
 let normalView='overview',normalHide=false;
 const stopVertical=installFaultKeys(sim,changed);
 $('#fault-route').onclick=()=>{normalView=viewMode();normalHide=!!$('#hide-npcs').checked;try{startFault(sim,{route:true});setView('explore');}catch(e){sim.message=e.message;}stopVertical();clearKeys();changed();};
 $('#fault-explore18').onclick=()=>{normalView=viewMode();normalHide=!!$('#hide-npcs').checked;try{startFault(sim,{climb:true});setView('explore');}catch(e){sim.message=e.message;}stopVertical();clearKeys();changed();};
 $('#fault-shutters-toggle').onclick=()=>{try{setFaultShutters(sim,!sim.fault.allShutters);}catch(e){sim.message=e.message;}changed();};
 for(const[kind,id]of[['up','climb-up'],['down','climb-down']])$('#'+id).onclick=()=>{sim.fault?.motion.commandClimb(kind);clearKeys();changed();};
 $('#fault-organic').onclick=()=>{normalView=viewMode();normalHide=!!$('#hide-npcs').checked;try{startFault(sim,{organic:true});setView('explore');}catch(e){sim.message=e.message;}stopVertical();clearKeys();changed();};
 $('#fault-brightness').oninput=e=>{if(sim.fault)sim.fault.brightness=Math.max(0,Math.min(100,Number(e.target.value)));changed();};
 for(const mode of ['A','B','C'])$('#fault-light-'+mode).onclick=()=>{selectFaultLight(sim,mode);changed();};
 $('#fault-flash').onclick=()=>{if(sim.fault)sim.fault.flashlight=!sim.fault.flashlight;changed();};
 const action=fn=>()=>{try{fn();}catch(e){sim.message=e.message;}stopVertical();clearKeys();changed();};
 $('#fault-start').onclick=action(()=>{normalView=viewMode();normalHide=!!$('#hide-npcs').checked;startFault(sim);$('#hide-npcs').checked=false;$('#hide-npcs').onchange?.({target:{checked:false}});setView('explore');});
 $('#fault-end').onclick=action(()=>{endFault(sim);$('#hide-npcs').checked=normalHide;$('#hide-npcs').onchange?.({target:{checked:normalHide}});setView(normalView);});
 $('#fault-walk').onclick=action(()=>sim.fault?.motion.walkMode());
 $('#fault-recover').onclick=action(()=>sim.fault?.motion.recover());
 for(const[id,axis]of[['fault-up',1],['fault-down',-1]]){const button=$('#'+id),stop=()=>{if(sim.fault)sim.fault.motion.axis=0;};button.onpointerdown=e=>{e.preventDefault();button.setPointerCapture?.(e.pointerId);sim.fault?.motion.setAxis(axis);};button.onpointerup=button.onpointercancel=button.onlostpointercapture=stop;}
 window.addEventListener('blur',()=>{if(sim.fault)sim.fault.motion.axis=0;});
 return{render(){const active=!!sim.fault;$('#fault-explore18').disabled=active||sim.mode!=='idle'||sim.anyLiftActive;$('#fault-shutters-toggle').disabled=!sim.fault?.climbEnabled||!!sim.fault?.motion?.climbMove;$('#fault-shutters-toggle').textContent=sim.fault?.allShutters?'シャッター：全開（指定開放へ）':'シャッター：指定開放（全開へ）';const targets=sim.fault?.motion.climbTargets()??{};for(const[kind,id]of[['up','climb-up'],['down','climb-down']]){$('#'+id).hidden=!targets[kind];$('#'+id).textContent=(kind==='up'?'↑ 登る Q':'↓ 降りる C')+(targets[kind]?'：'+targets[kind].target:'');}$('#climb-status').textContent=sim.fault?.motion.climbMove?'支持昇降中：'+sim.fault.motion.climbMove.target:'';$('#fault-organic').disabled=active||sim.mode!=='idle'||sim.anyLiftActive;$('#fault-brightness').disabled=!active;if(active){$('#fault-brightness').value=sim.fault.brightness??LIGHT_LEVELS[sim.fault.lighting];$('#fault-brightness-value').textContent=$('#fault-brightness').value+'%';$('#fault-flash').textContent='懐中電灯：'+(sim.fault.flashlight?'ON':'OFF')+'（L）';}$('#fault-route').disabled=active||sim.mode!=='idle'||sim.anyLiftActive;for(const id of['fault-light-A','fault-light-B','fault-light-C','fault-flash'])$('#'+id).disabled=!active;$('#fault-start').disabled=active||sim.mode!=='idle'||sim.anyLiftActive;for(const id of['fault-end','fault-up','fault-down','fault-walk','fault-recover'])$('#'+id).disabled=!active;
 for(const id of['start','pause','apply-experiment','experiment-size','experiment-method','save-life','load-life','reset','auto-enabled','exception-add','exception-remove','exception-exit','lift-button','lab-debug-reconnect','inventory-open','item-use-open','trade-open','parcel-get','hide-npcs'])$('#'+id).disabled=active;
 document.querySelectorAll('[data-location]').forEach(b=>b.disabled=active);
 document.querySelectorAll('[data-plan]').forEach(b=>b.disabled=active);
 $('#fault-status').textContent=active?'故障実験 / '+(sim.fault.motion.climbMove?'支持昇降中':sim.fault.motion.control==='free'?'開発専用の上下移動（押している間）':sim.fault.motion.grounded?'通常歩行・足場あり':'通常歩行・自由落下'):'通常ABC運用 / 故障試験は指定状態を再現';
 if(!active)return false;
 $('#life-panel').hidden=true;$('#dialogue').hidden=true;$('#booth-view').hidden=true;$('#lift-menu').hidden=true;$('#life-clock').textContent='故障試験中：生活時計停止';$('#life-status').textContent='通常の生活状態は復帰時に戻します。';
 const p=sim.player,m=sim.fault.motion;$('#sequence').textContent='A → B（故障停止）';$('#progress').style.width=(sim.fault.time/sim.plan.duration*100)+'%';$('#reachable-count').textContent='—';$('#camera-caption').textContent='FAULT EXPERIMENT / AB 4.3s';$('#scene-title').textContent='室内から、停止したチャンクの屋根へ';$('#scene-subtitle').textContent='故障配置を保持 / 床のない場所では自由落下';$('#experiment-summary').textContent='故障試験の検証済み設定：一回り・協調搬送';$('#phase-badge').textContent='故障 A→B';$('#phase-description').textContent='4.3秒の中間配置で固定';$('#transfer-status').textContent='故障停止・実形状で探索';$('#stage-label').textContent=sim.fault.climbEnabled?'Q：登る・C：降りる（縁に近づき対象を見る）。全開／指定開放を比較可能。R/Fは開発用。':sim.fault.organic?'R2東→L1屋根→繊維→V3屋根→V1屋根→繊維を上ってV3南口→北口（E）。R/F上下・L照射。':'R/F：上下・L：懐中電灯。第16経路：SM0東→SM1屋根→BR3屋根→SM1北口→西口（E手動）。';$('#player-location').textContent=(p.owner??'搬送空間')+' / '+(m.climbMove?'支持昇降中':m.control==='free'?'開発上下移動':m.grounded?'足場上':'落下中');$('#coordinates').textContent=`X ${p.x.toFixed(2)} Y ${p.y.toFixed(2)} Z ${p.z.toFixed(2)}`;$('#message').textContent=sim.message;
 $('#map-upper').innerHTML=faultMapSVG(sim);$('#map-lower').innerHTML='<p>故障時は上図に全高さの実位置を投影しています。</p>';$('#map-first').innerHTML='';$('#map-deck').innerHTML=faultMapSVG(sim);$('#map-note').textContent='通常のA/B完成配置の経路グラフは表示しません。ラベルのYは停止床高です。';$('#selected-detail').textContent='故障中：完成配置の接続診断は無効。外形は俯瞰、足場は実際のメッシュで確認してください。';return true;}};
}
